          imageenabled: "off",
          imagelink: "",
          text_lang: {
            en: "<p>E<strong>istauchen – das ist zwar flott ausgesprochen, aber extrem anspruchsvoll. Unter der geschlossenen Eisdecke unterwegs zu sein, erfordert eine ordentliche Portion Abenteuerlust, im Zweifelsfall überlebenswichtiges Wissen, den Wunsch, die eigene Komfortzone zu verlassen – und ein Quäntchen Wahnsinn. Aber Hand aufs Herz: Ist es nicht so, dass ziemlich viele gute Tauchtage mit dem Satz “Was zum Teufel mache ich eigentlich hier?“ beginnen?</strong></p><p>Zu Beginn des Jahres 2022 spendierte das Wetter endlich alle “Reize“ eines echten Winters. Die Temperaturen lagen tagelang im Minusbereich, der Schnee fiel und fiel mit kurzen Unterbrechungen, ohne Tauwetter in Sicht. Ideale Bedingungen also, um sich auf ein Eistauchabenteuer einzulassen.</p>",
          },
          imageurl:
            "https://cfstock.s3.amazonaws.com/components/image/placeholder.jpg",
          text: "<p>E<strong>istauchen – das ist zwar flott ausgesprochen, aber extrem anspruchsvoll. Unter der geschlossenen Eisdecke unterwegs zu sein, erfordert eine ordentliche Portion Abenteuerlust, im Zweifelsfall überlebenswichtiges Wissen, den Wunsch, die eigene Komfortzone zu verlassen – und ein Quäntchen Wahnsinn. Aber Hand aufs Herz: Ist es nicht so, dass ziemlich viele gute Tauchtage mit dem Satz “Was zum Teufel mache ich eigentlich hier?“ beginnen?</strong></p><p>Zu Beginn des Jahres 2022 spendierte das Wetter endlich alle “Reize“ eines echten Winters. Die Temperaturen lagen tagelang im Minusbereich, der Schnee fiel und fiel mit kurzen Unterbrechungen, ohne Tauwetter in Sicht. Ideale Bedingungen also, um sich auf ein Eistauchabenteuer einzulassen.</p>",
