          linktype: "none",
          imagefloat: "left",
          externallinktarget: "off",
          imageenabled: "off",
          imagelink: "",
          text_lang: {
            en: "<p>Sobald man den Karawanken-Tunnel von Slowenien aus durchfährt, betritt man Österreich. Uns kam es so vor, als wären wir nach dem Tunnel erst wirklich im Winter angekommen. Die dicke Schneedecke auf der anderen Seite des Berges formte zur Begrüßung die perfekte Winterlandschaft und schürte die Vorfreude auf unser Ziel: Schließlich gilt der Weißensee als einer der besten Orte zum Eistauchen in diesem Teil Europas.</p><p>Unser Bergjuwel ist eiszeitlichen Ursprungs und liegt im Bundesland Kärnten auf einer Höhe von 945 Metern über dem Meeresspiegel. An den Ufern des Sees liegt der Ort Techendorf mit nur wenigen hundert Einwohnern, die zum größten Teil vom Tourismus leben. Bei 11,6 Kilometern Länge und maximal knapp einem Kilometer Breite kommt der See auf etwa 27 Kilometer Küstenlinie. Der nördliche Teil ist dabei bewohnt, während der südliche Teil ein Naturpark ist, der auch heute noch einigermaßen wild und unberührt ist. Im südlichen Becken erreicht der See je nach Wasserstand etwa 100 Meter Tiefe. Die verlässliche “Eiszeit“ beginnt Ende Dezember und dauert üblicherweise bis in die ersten Märztage. Über die lange Saison freuen sich natürlich nicht nur Schlittschuhläufer und viele andere, die auf dem Eis unterwegs sind, sondern auch die etwas spezielleren Gäste auf der anderen Seite der Eisfläche...</p>",
          },
          imageurl:
            "https://cfstock.s3.amazonaws.com/components/image/placeholder.jpg",
          text: "<p>Sobald man den Karawanken-Tunnel von Slowenien aus durchfährt, betritt man Österreich. Uns kam es so vor, als wären wir nach dem Tunnel erst wirklich im Winter angekommen. Die dicke Schneedecke auf der anderen Seite des Berges formte zur Begrüßung die perfekte Winterlandschaft und schürte die Vorfreude auf unser Ziel: Schließlich gilt der Weißensee als einer der besten Orte zum Eistauchen in diesem Teil Europas.</p><p>Unser Bergjuwel ist eiszeitlichen Ursprungs und liegt im Bundesland Kärnten auf einer Höhe von 945 Metern über dem Meeresspiegel. An den Ufern des Sees liegt der Ort Techendorf mit nur wenigen hundert Einwohnern, die zum größten Teil vom Tourismus leben. Bei 11,6 Kilometern Länge und maximal knapp einem Kilometer Breite kommt der See auf etwa 27 Kilometer Küstenlinie. Der nördliche Teil ist dabei bewohnt, während der südliche Teil ein Naturpark ist, der auch heute noch einigermaßen wild und unberührt ist. Im südlichen Becken erreicht der See je nach Wasserstand etwa 100 Meter Tiefe. Die verlässliche “Eiszeit“ beginnt Ende Dezember und dauert üblicherweise bis in die ersten Märztage. Über die lange Saison freuen sich natürlich nicht nur Schlittschuhläufer und viele andere, die auf dem Eis unterwegs sind, sondern auch die etwas spezielleren Gäste auf der anderen Seite der Eisfläche...</p>",
