          linktype: "none",
          imagefloat: "left",
          externallinktarget: "off",
          imageenabled: "off",
          imagelink: "",
          text_lang: {
            en: "<p>Ohne den “Eismeister“ geht dabei nichts: Er kontrolliert täglich den Zustand der Eisfläche und beaufsichtigt die Aktivitäten auf dem See. Er kann die Öffnung von Tauchlöchern genehmigen, aber auch jede Aktivität verbieten, wenn er den Zustand des Eises für schlecht hält. Wenn der See im Winter aber einmal wirklich zugefroren ist, bleiben die Verhältnisse im Allgemeinen bis zum Ende der Saison stabil und fest.</p><p>Jenseits der Wasseroberfläche ist Ernest Turnschek der Chef. Sein Tauchzentrum “Yacht Diver“ ist aufs Eistauchen spezialisiert, sodass Taucher aus ganz Europa hierher kommen, um den Extremsport dank vorbildlicher Rahmenbedingungen sicher genießen zu können. Das gesamte Unterfangen, das für solche Tauchgänge unerlässlich, schlichtweg sehr gut organisiert – vom Öffnen der Einstiegslöcher über den Transport der Ausrüstung auf dem Eis bis hin zu Sicherheit und Rettungskette, oder selbst, wenn es um einen Zugang zu abgelegenen Bereichen des Sees geht. So sind etwa Schlitten, Quads und Schneemobile verfügbar. Aufgrund der ansprechenden Infrastruktur wird der See auch regelmäßig für besondere Veranstaltungen genutzt, wie Apnoe-Rekordversuche oder die “Tage der Unterwasserfotografie“ unter Eis, wobei es Ernest und sein erfahrenes Team sind, die all das möglich machen. Übrigens: 1987 wurden einige Szenen aus dem JamesBond-Film “Der Hauch des Todes“ auf dem See gedreht.</p><p>Nervöse Gemüter wird es beruhigen: Das Eis ist in der Regel 20 bis 30 Zentimeter dick, so dass man sich sicher auf der Oberfläche bewegen kann. Und weil sich die Österreicher oft bis ins kleinste Detail um den Umweltschutz bemühen, werden die Einstiegslöcher mit Kettensägen geschnitten, die zur Schmierung Bioöl verwenden. Bei unseren Tauchgängen in verschiedenen Teilen des Weißensees bekamen wir mehr Vielfalt zu Gesicht, als mancher erwarten würde: Neben den typischen alpinen Unterwasserlandschaften entdeckten wir überflutete Wäldchen, felsige Mündungen von Gebirgsbächen, aber auch flache, mit Schilf bewachsene Bereiche. Die Sichtweite betrug stets zehn bis 15 Meter, auch wenn das Wasser die übliche grünliche Farbe hatte. Aber wen stört das schon, wenn das Kältehoch herrliches Sonnenwetter mit einstelligen Minustemperaturen spendiert und die Bedingungen zum Tauchen schlichtweg ideal sind.</p>",
          },
          imageurl:
            "https://cfstock.s3.amazonaws.com/components/image/placeholder.jpg",
          text: "<p>Ohne den “Eismeister“ geht dabei nichts: Er kontrolliert täglich den Zustand der Eisfläche und beaufsichtigt die Aktivitäten auf dem See. Er kann die Öffnung von Tauchlöchern genehmigen, aber auch jede Aktivität verbieten, wenn er den Zustand des Eises für schlecht hält. Wenn der See im Winter aber einmal wirklich zugefroren ist, bleiben die Verhältnisse im Allgemeinen bis zum Ende der Saison stabil und fest.</p><p>Jenseits der Wasseroberfläche ist Ernest Turnschek der Chef. Sein Tauchzentrum “Yacht Diver“ ist aufs Eistauchen spezialisiert, sodass Taucher aus ganz Europa hierher kommen, um den Extremsport dank vorbildlicher Rahmenbedingungen sicher genießen zu können. Das gesamte Unterfangen, das für solche Tauchgänge unerlässlich, schlichtweg sehr gut organisiert – vom Öffnen der Einstiegslöcher über den Transport der Ausrüstung auf dem Eis bis hin zu Sicherheit und Rettungskette, oder selbst, wenn es um einen Zugang zu abgelegenen Bereichen des Sees geht. So sind etwa Schlitten, Quads und Schneemobile verfügbar. Aufgrund der ansprechenden Infrastruktur wird der See auch regelmäßig für besondere Veranstaltungen genutzt, wie Apnoe-Rekordversuche oder die “Tage der Unterwasserfotografie“ unter Eis, wobei es Ernest und sein erfahrenes Team sind, die all das möglich machen. Übrigens: 1987 wurden einige Szenen aus dem JamesBond-Film “Der Hauch des Todes“ auf dem See gedreht.</p><p>Nervöse Gemüter wird es beruhigen: Das Eis ist in der Regel 20 bis 30 Zentimeter dick, so dass man sich sicher auf der Oberfläche bewegen kann. Und weil sich die Österreicher oft bis ins kleinste Detail um den Umweltschutz bemühen, werden die Einstiegslöcher mit Kettensägen geschnitten, die zur Schmierung Bioöl verwenden. Bei unseren Tauchgängen in verschiedenen Teilen des Weißensees bekamen wir mehr Vielfalt zu Gesicht, als mancher erwarten würde: Neben den typischen alpinen Unterwasserlandschaften entdeckten wir überflutete Wäldchen, felsige Mündungen von Gebirgsbächen, aber auch flache, mit Schilf bewachsene Bereiche. Die Sichtweite betrug stets zehn bis 15 Meter, auch wenn das Wasser die übliche grünliche Farbe hatte. Aber wen stört das schon, wenn das Kältehoch herrliches Sonnenwetter mit einstelligen Minustemperaturen spendiert und die Bedingungen zum Tauchen schlichtweg ideal sind.</p>",
          cacheparam: 1,
