                imageenabled: "off",
                imagelink: "",
                text_lang: {
                  en: "<p>Im Gegensatz zu normalen Tauchgängen muss beim Eistauchen jederzeit ein aufmerksamer Helfer bereitstehen. Der Einstieg ins Wasser erfolgt nacheinander.</p>",
                },
                imageurl:
                  "https://cfstock.s3.amazonaws.com/components/image/placeholder.jpg",
                text: "<p>Im Gegensatz zu normalen Tauchgängen muss beim Eistauchen jederzeit ein aufmerksamer Helfer bereitstehen. Der Einstieg ins Wasser erfolgt nacheinander.</p>",
                cacheparam: 1,
