          linktype: "none",
          imagefloat: "left",
          externallinktarget: "off",
          imageenabled: "off",
          imagelink: "",
          text_lang: {
            en: "<p>Rund tausend Kilometer von Weißensee entfernt auf dem Balkan, zeigt der Ribnica-See in Serbien eine ganz andere Facette des Eistauchens – sowohl, wenn es um das Revier selbst geht, als auch um das Drumherum. Am benachbarten Berg Zlatibor fallen teils extreme Niederschläge, so dass der See in wesentlichen Teilen durch Wasser aus Bergbächen gespeist wird und als Trinkwasserreservoir dient. Daher ist für das Tauchen eine Sondergenehmigung erforderlich, die wir zwar relativ schnell erhielten. Wir bekamen sie relativ schnell, waren aber umso verblüffter als wir rausfanden, dass wir die ersten waren, die dort im Winter und noch dazu unter dem Eis tauchen wollten...</p><p>Mit zwei Kilometern Länge und einer maximalen Tiefe von 25 Metern ist der See auf 956 Metern über Meereshöhe zwar angenehm überschaubar, dafür kündigten die Meteorologen um unsere Tauchtage herum für den Balkan und Serbien eine Kältewelle an mit Nachttemperaturen von -20 Grad Celsius. Einerseits freuten wir uns, weil das Eis tragfähig sein würde, andererseits könnte unser Tauchequipment spielend leicht einfrieren.</p><p>Am ersten Tauchtag empfing uns die ganze Idylle einer Winterlandschaft mit einem von Schnee und Eis umgebenen See mitsamt dem Gipfel des Zlatibor in seiner ganzen Schönheit. Praktischerweise befindet sich auf der anderen Seite des Sees eine Seilbahn, die Touristen bis zum Skigipfel Tornik hinauffährt. Das Personal an der Zwischenstation war so freundlich, den Weg durch den Wald zum See freizumachen und so kamen wir mit unseren Fahrzeugen ohne größere Probleme fast bis an den Rand der Eisdecke. Schnell war der Beschluss gefasst, ein rundes und ein klassisch dreieckiges Loch im Eis zu öffnen. Kurz darauf schallte das Dröhnen einer Kettensäge über die schneebedeckten Wiesen von Zlatibor...</p><p>Mit einem Team aus erfahrenen und entsprechend ausgebildeten Tauchern unseres Vereins Svet Ronjenja ging das Öffnen der Löcher ebenso reibungslos vonstatten wie die Prüfung der Eisplatte. 15 bis 20 Zentimeter Durchmesser reichten allemal für eine sichere Bewegung auf dem Eis. Von der Gondel über uns blickten die Ausflugsgäste unmittelbar hinab auf zwei schwarze Löcher im Eis – gäbe es Tore zu einer anderen Welt, dann würden sie in meiner Vorstellung genau so ausschauen.</p><p>In zwei Teams gingen wir unser Ziel an, grundlegende Informationen über die Bedingungen unter dem Eis zu sammeln und diese mit Fotos zu dokumentieren. Die Wassertemperatur von zwei Grad Celsius war für unsere Ausrüstungen schon einmal eine gute Nachricht und für uns selbst das dunkle, dafür aber sehr klare Wasser. Was uns die Sprache verschlug, war die Farbe der eiskalten Fluten an der Oberfläche: Niemand mag sich bei den Temperaturen die Augen reiben und anschließend die Maske ausblasen, aber das Wasser war tatsächlich fast orange.</p>",
          },
          imageurl:
            "https://cfstock.s3.amazonaws.com/components/image/placeholder.jpg",
          text: "<p>Rund tausend Kilometer von Weißensee entfernt auf dem Balkan, zeigt der Ribnica-See in Serbien eine ganz andere Facette des Eistauchens – sowohl, wenn es um das Revier selbst geht, als auch um das Drumherum. Am benachbarten Berg Zlatibor fallen teils extreme Niederschläge, so dass der See in wesentlichen Teilen durch Wasser aus Bergbächen gespeist wird und als Trinkwasserreservoir dient. Daher ist für das Tauchen eine Sondergenehmigung erforderlich, die wir zwar relativ schnell erhielten. Wir bekamen sie relativ schnell, waren aber umso verblüffter als wir rausfanden, dass wir die ersten waren, die dort im Winter und noch dazu unter dem Eis tauchen wollten...</p><p>Mit zwei Kilometern Länge und einer maximalen Tiefe von 25 Metern ist der See auf 956 Metern über Meereshöhe zwar angenehm überschaubar, dafür kündigten die Meteorologen um unsere Tauchtage herum für den Balkan und Serbien eine Kältewelle an mit Nachttemperaturen von -20 Grad Celsius. Einerseits freuten wir uns, weil das Eis tragfähig sein würde, andererseits könnte unser Tauchequipment spielend leicht einfrieren.</p><p>Am ersten Tauchtag empfing uns die ganze Idylle einer Winterlandschaft mit einem von Schnee und Eis umgebenen See mitsamt dem Gipfel des Zlatibor in seiner ganzen Schönheit. Praktischerweise befindet sich auf der anderen Seite des Sees eine Seilbahn, die Touristen bis zum Skigipfel Tornik hinauffährt. Das Personal an der Zwischenstation war so freundlich, den Weg durch den Wald zum See freizumachen und so kamen wir mit unseren Fahrzeugen ohne größere Probleme fast bis an den Rand der Eisdecke. Schnell war der Beschluss gefasst, ein rundes und ein klassisch dreieckiges Loch im Eis zu öffnen. Kurz darauf schallte das Dröhnen einer Kettensäge über die schneebedeckten Wiesen von Zlatibor...</p><p>Mit einem Team aus erfahrenen und entsprechend ausgebildeten Tauchern unseres Vereins Svet Ronjenja ging das Öffnen der Löcher ebenso reibungslos vonstatten wie die Prüfung der Eisplatte. 15 bis 20 Zentimeter Durchmesser reichten allemal für eine sichere Bewegung auf dem Eis. Von der Gondel über uns blickten die Ausflugsgäste unmittelbar hinab auf zwei schwarze Löcher im Eis – gäbe es Tore zu einer anderen Welt, dann würden sie in meiner Vorstellung genau so ausschauen.</p><p>In zwei Teams gingen wir unser Ziel an, grundlegende Informationen über die Bedingungen unter dem Eis zu sammeln und diese mit Fotos zu dokumentieren. Die Wassertemperatur von zwei Grad Celsius war für unsere Ausrüstungen schon einmal eine gute Nachricht und für uns selbst das dunkle, dafür aber sehr klare Wasser. Was uns die Sprache verschlug, war die Farbe der eiskalten Fluten an der Oberfläche: Niemand mag sich bei den Temperaturen die Augen reiben und anschließend die Maske ausblasen, aber das Wasser war tatsächlich fast orange.</p>",
