          imageenabled: "off",
          imagelink: "",
          text_lang: {
            en: "<p>Als professionelles Unterwassermodell hat Ivana Orlovic in verschiedenen Meeren, Ozeanen, Seen und Flüssen auf der ganzen Welt posiert, wo das Wasser mal bläulich, grün oder so klar ist, dass man meinen könnte, es existiere gar nicht, doch auch für sie war es das erste Mal, dass sie Bekanntschaft mit vollkommen transparentem, aber orangegelbem Wasser gemacht hat – am ehesten, so berichtet sie, kämen noch einige Cenoten auf der mexikanischen Halbinsel Yucatán an solche Verhältnisse heran. Ursächlich für die Farbe des Seewassers ist die Art der Sedimente auf dem Grund – im Ribnica-See besteht der Boden aus charakteristisch orangefarbenem Staub und dunklen Steinen –, zahlreiche Nährstoffe aus den umliegenden Nadelwäldern und das Vorhandensein von Algen.</p><p>In den tieferen Bereichen verschwindet das Licht fast völlig, dafür wird die Sicht besser und das Wasser verliert seine markante Färbung. Bei unseren wenigen Tauchgängen ließen sich ziemlich kapitale Flussbarsche beobachten, und wenn man den Erzählungen der Sportfischer glauben darf, ist der See grundsätzlich sehr fischreich. Um den Beweis anzutreten, warten wir dann allerdings doch mal aufs Frühjahr.</p>",
          },
          imageurl:
            "https://cfstock.s3.amazonaws.com/components/image/placeholder.jpg",
          text: "<p>Als professionelles Unterwassermodell hat Ivana Orlovic in verschiedenen Meeren, Ozeanen, Seen und Flüssen auf der ganzen Welt posiert, wo das Wasser mal bläulich, grün oder so klar ist, dass man meinen könnte, es existiere gar nicht, doch auch für sie war es das erste Mal, dass sie Bekanntschaft mit vollkommen transparentem, aber orangegelbem Wasser gemacht hat – am ehesten, so berichtet sie, kämen noch einige Cenoten auf der mexikanischen Halbinsel Yucatán an solche Verhältnisse heran. Ursächlich für die Farbe des Seewassers ist die Art der Sedimente auf dem Grund – im Ribnica-See besteht der Boden aus charakteristisch orangefarbenem Staub und dunklen Steinen –, zahlreiche Nährstoffe aus den umliegenden Nadelwäldern und das Vorhandensein von Algen.</p><p>In den tieferen Bereichen verschwindet das Licht fast völlig, dafür wird die Sicht besser und das Wasser verliert seine markante Färbung. Bei unseren wenigen Tauchgängen ließen sich ziemlich kapitale Flussbarsche beobachten, und wenn man den Erzählungen der Sportfischer glauben darf, ist der See grundsätzlich sehr fischreich. Um den Beweis anzutreten, warten wir dann allerdings doch mal aufs Frühjahr.</p>",
          cacheparam: 1,
