                linktype: "none",
                imagefloat: "left",
                externallinktarget: "off",
                imageenabled: "off",
                imagelink: "",
                text_lang: {
                  en: "<p>Tauchen unter einer geschlossenen Eisdecke kann alle möglichen Probleme mit sich bringen, nicht zuletzt die unvorhersehbaren täglichen Schwankungen: Unser erster Tauchtag war sonnig und kalt, mit einer Außentemperatur von -17 Grad Celsius, während der zweite Tag etwas wärmer war (-10 Grad Celsius), aber bewölkt und mäßig windig. Das bereitete uns große Probleme, weil alles zu frieren begann. Seile und Tarierjackets froren steif, und die Atemregler begannen auf dem Trockenen zu gefrieren. Aber mit ein paar kleinen Tricks funktionierte alles wieder, sobald wir ins Wasser gingen. Die Organisation solcher Tauchgänge ist nicht unproblematisch und erfordert eine genaue Planung und Vorbereitung der Ausrüstung. Wenn dann noch Fotoaufnahmen unter eisigen Bedingungen hinzukommen, wird es kein Zuckerschlecken. Viele kleine Dinge können schiefgehen und die Umsetzung der Pläne erschweren oder gar völlig unmöglich machen. Deshalb ist es wichtig, alles gut zu planen und sich dann auch an den Plan zu halten. Andererseits muss man auf Änderungen vor Ort vorbereitet zu sein und improvisieren können, wenn es denn nötig ist. Außerdem braucht man eine gesunde Portion Glück mit dem Wetter! Bei unseren frostigen Abenteuern fielen die Würfel günstig und unser Fotoshooting konnte nach Plan verlaufen. Und das ist beileibe keine Selbstverständlichkeit.</p>",
                },
                imageurl:
                  "https://cfstock.s3.amazonaws.com/components/image/placeholder.jpg",
                text: "<p>Tauchen unter einer geschlossenen Eisdecke kann alle möglichen Probleme mit sich bringen, nicht zuletzt die unvorhersehbaren täglichen Schwankungen: Unser erster Tauchtag war sonnig und kalt, mit einer Außentemperatur von -17 Grad Celsius, während der zweite Tag etwas wärmer war (-10 Grad Celsius), aber bewölkt und mäßig windig. Das bereitete uns große Probleme, weil alles zu frieren begann. Seile und Tarierjackets froren steif, und die Atemregler begannen auf dem Trockenen zu gefrieren. Aber mit ein paar kleinen Tricks funktionierte alles wieder, sobald wir ins Wasser gingen. Die Organisation solcher Tauchgänge ist nicht unproblematisch und erfordert eine genaue Planung und Vorbereitung der Ausrüstung. Wenn dann noch Fotoaufnahmen unter eisigen Bedingungen hinzukommen, wird es kein Zuckerschlecken. Viele kleine Dinge können schiefgehen und die Umsetzung der Pläne erschweren oder gar völlig unmöglich machen. Deshalb ist es wichtig, alles gut zu planen und sich dann auch an den Plan zu halten. Andererseits muss man auf Änderungen vor Ort vorbereitet zu sein und improvisieren können, wenn es denn nötig ist. Außerdem braucht man eine gesunde Portion Glück mit dem Wetter! Bei unseren frostigen Abenteuern fielen die Würfel günstig und unser Fotoshooting konnte nach Plan verlaufen. Und das ist beileibe keine Selbstverständlichkeit.</p>",
